model.eval()


def finite_check():
    enc = tok([chat("Write one sentence about the ocean.")], return_tensors="pt", add_special_tokens=False).to("cuda:0")
    with torch.no_grad():
        lg = model(**enc).logits
    return bool(torch.isfinite(lg).all())


